    "milestones": [
      {
        "task": "find acacia_door",
        "milestone_id": "find_acacia_door",
        "description": "Uses position_near_with_facing because this is a find/locate task. The acacia door is at spawn-relative position (8, 1, 6). Max distance reduced to 5 (from 16) per CommonSenseAgent and ValidatorAgent feedback — the door is ~10 blocks from spawn, so 16 would allow the player to satisfy this from near spawn without meaningful navigation. A max_distance of 5 ensures the player has walked up to the door. Facing tolerance of 60 degrees confirms they are looking at it.",
        "rules": [
          {
            "type": "position_near_with_facing",
            "params": {
              "target": [8, 1, 6],
              "max_distance": 5,
              "facing_tolerance": 60,
              "coordinate_frame": "spawn_relative"
            }
          }
        ]
      },
      {
        "task": "find potted_red_tulip",
        "milestone_id": "find_potted_red_tulip",
        "description": "Uses position_near_with_facing because this is a find/locate task. The potted red tulip is at spawn-relative position (7, 1, 11) inside the farmhouse on a table (oak_stairs block). Max distance of 5 blocks ensures the player must be inside or at the back of the house to satisfy this — they cannot see it from outside the front door (the tulip is ~5 blocks from the door at the back-left corner). Facing tolerance of 60 degrees confirms they are looking at the tulip.",
        "rules": [
          {
            "type": "position_near_with_facing",
            "params": {
              "target": [7, 1, 11],
              "max_distance": 5,
              "facing_tolerance": 60,
              "coordinate_frame": "spawn_relative"
            }
          }
        ]
      },
      {
        "task": "mine carrots",
        "milestone_id": "mine_carrots",
        "description": "Uses inventory_has because mining mature carrot crops (age=7) drops carrot items directly into the player's inventory. The item type is 'carrot' (singular, no minecraft: prefix). Requiring min_count of 1 means the player has successfully broken at least one mature carrot crop and collected the drop. No tools are needed — carrots can be broken by hand in survival mode. The player starts with an empty inventory so any carrot in inventory confirms mining.",
        "rules": [
          {
            "type": "inventory_has",
            "params": {
              "item": "carrot",
              "min_count": 1
